(()=>{'use strict';
const $=id=>document.getElementById('pg-'+id),MAX=500000;let worker=null,result=null,sources=null,revision=0;
const exampleA='Our software platform helps designers create digital content. Creative software supports image editing, video editing and document workflows. Customers subscribe to cloud software and digital content tools. The platform integrates creative applications and document services. Designers use creative software to produce digital content.';
const exampleB='Our computing platform supports artificial intelligence and accelerated computing. Graphics processors power data centers and visual computing. Customers use graphics processors for machine learning and artificial intelligence. The platform combines computing hardware, software libraries and cloud services. Data centers deploy accelerated computing systems.';
function clearResults(){revision++;worker?.terminate();worker=null;result=null;sources=null;$('results').hidden=true;$('analyze').disabled=false;$('status').textContent='Inputs changed. Analyze to refresh the results.';}
for(const key of ['a','b','extra','phrases'])$(key).addEventListener('input',clearResults);
for(const key of ['a','b'])$('file-'+key).addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;clearResults();const rev=revision;if(!/\.txt$/i.test(f.name)||f.size>2*1024*1024){$('status').textContent='Choose a UTF-8 .txt file up to 2 MB. PDF and Word files are not supported; paste their text instead.';e.target.value='';return;}const text=await f.text();if(rev!==revision)return;if(text.length>MAX){$('status').textContent='This file exceeds 500,000 characters. Please use a shorter extract; nothing has been truncated.';return;}$(key).value=text;$('status').textContent='Loaded '+f.name+' locally. Select Analyze text to continue.';});
$('example').onclick=()=>{clearResults();$('a').value=exampleA;$('b').value=exampleB;$('status').textContent='Two synthetic sample descriptions loaded. Select Analyze text.';};
$('clear').onclick=()=>{clearResults();for(const k of ['a','b','extra','file-a','file-b'])$(k).value='';$('status').textContent='Cleared. Paste Text A to begin.';};
$('analyze').onclick=()=>{clearResults();const a=$('a').value,b=$('b').value;if(!a.trim()){$('status').textContent='Add Text A first. Text B is optional.';$('a').focus();return;}if(a.length>MAX||b.length>MAX){$('status').textContent='Each text is limited to 500,000 characters. Please shorten the input; nothing has been truncated.';return;}
 sources={a,b};$('status').textContent='Processing text locally…';$('analyze').disabled=true;const rev=revision;
 try{worker=new Worker('playground-worker.js');worker.onmessage=({data})=>{if(rev!==revision)return;worker.terminate();worker=null;$('analyze').disabled=false;if(data.error){$('status').textContent=data.error;return;}result=data;render();};worker.onerror=()=>{$('analyze').disabled=false;$('status').textContent='Local processing could not start. Refresh this page and try again.';worker?.terminate();worker=null;};worker.postMessage({a,b,extra:$('extra').value,phrases:$('phrases').checked});}catch(e){$('analyze').disabled=false;$('status').textContent='This browser could not start the local text processor.';}
};
function cloud(canvas,terms,max){const c=canvas.getContext('2d'),W=900,H=480;c.clearRect(0,0,W,H);const boxes=[],colors=['#443983','#21918c','#31688e','#35a878','#7554a3','#657c36'];let placed=0;for(const [i,t] of terms.slice(0,45).entries()){let size=15+75*Math.pow(t.rate/max,.8),found=false;while(size>=12&&!found){c.font='600 '+Math.round(size)+'px Arial';const w=c.measureText(t.term).width+12,h=size+7;for(let k=0;k<3500;k++){const angle=k*.35,r=3.8*Math.sqrt(k),x=W/2+Math.cos(angle)*r*1.85-w/2,y=H/2+Math.sin(angle)*r-h/2;if(x<4||y<4||x+w>W-4||y+h>H-4||boxes.some(b=>x<b.x+b.w&&x+w>b.x&&y<b.y+b.h&&y+h>b.y))continue;boxes.push({x,y,w,h});c.fillStyle=colors[i%colors.length];c.textBaseline='middle';c.fillText(t.term,x+6,y+h/2);placed++;found=true;break;}size*=.86;}}
 canvas.setAttribute('aria-label',placed+' keywords. '+terms.slice(0,8).map(t=>t.term).join(', ')+'. Exact counts appear in the table.');return placed;}
function node(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}
function render(){const {a,b}=result;$('results').hidden=false;$('clouds').classList.toggle('single',!b);$('card-b').hidden=!b;$('metrics').replaceChildren();for(const [name,x] of [['A',a],['B',b]])if(x)$('metrics').append(node('span',`Text ${name}: ${x.raw.toLocaleString()} English tokens → ${x.kept.toLocaleString()} retained`));
 const max=Math.max(1,...a.terms.slice(0,45).map(t=>t.rate),...(b?b.terms.slice(0,45).map(t=>t.rate):[]));for(const [key,x] of [['a',a],['b',b]])if(x){const n=cloud($('cloud-'+key),x.terms,max);$('meta-'+key).textContent=n+' displayed terms · size = occurrences per 10k retained words';}
 const ma=new Map(a.terms.map(t=>[t.term,t])),mb=new Map(b?.terms.map(t=>[t.term,t])||[]);let rows;
 if(b){const singles=x=>x.terms.filter(t=>!t.term.includes(' '));const va=new Map(singles(a).map(t=>[t.term,t.count])),vb=new Map(singles(b).map(t=>[t.term,t.count]));let dot=0,aa=0,bb=0;for(const [t,c]of va){aa+=c*c;dot+=c*(vb.get(t)||0);}for(const c of vb.values())bb+=c*c;const cosine=aa&&bb?dot/Math.sqrt(aa*bb):null;$('metrics').append(node('span',cosine===null?'Lexical cosine: unavailable':'Lexical cosine: '+cosine.toFixed(3)));
 rows=[...new Set([...ma.keys(),...mb.keys()])].map(term=>({term,a:ma.get(term),b:mb.get(term)}));const shared=rows.filter(t=>t.a&&t.b).sort((x,y)=>Math.min(y.a.rate,y.b.rate)-Math.min(x.a.rate,x.b.rate)).slice(0,15);const da=rows.filter(t=>(t.a?.rate||0)>(t.b?.rate||0)).sort((x,y)=>((y.a?.rate||0)-(y.b?.rate||0))-((x.a?.rate||0)-(x.b?.rate||0))).slice(0,10);const db=rows.filter(t=>(t.b?.rate||0)>(t.a?.rate||0)).sort((x,y)=>((y.b?.rate||0)-(y.a?.rate||0))-((x.b?.rate||0)-(x.a?.rate||0))).slice(0,10);rows=[...shared.map(x=>({...x,label:'Shared'})),...da.map(x=>({...x,label:'More prominent in A'})),...db.map(x=>({...x,label:'More prominent in B'}))];
 }else rows=a.terms.slice(0,30).map(t=>({term:t.term,a:t,label:'Top keyword'}));
 $('rows').replaceChildren();for(const x of rows){const tr=node('tr',''),td=node('td',''),btn=node('button',x.term);btn.type='button';btn.onclick=()=>evidence(x.term);td.append(btn);tr.append(td,node('td',x.label),node('td',format(x.a)),node('td',b?format(x.b):'—'));$('rows').append(tr);}
 $('source').hidden=true;$('status').textContent=a.kept?'Analysis complete. Select a keyword to inspect its original context.':'No usable English terms remain. Try English prose or reduce the excluded words.';if(b&&!b.kept)$('status').textContent+=' Text B has no retained English terms; similarity is unavailable.';
 }
function format(t){return t?t.count+' · '+t.rate.toFixed(1):'0 · 0.0';}
function evidence(term){$('source').hidden=false;$('source').replaceChildren(node('h4','Source context: '+term));for(const key of ['a','b']){if(key==='b'&&!result.b)continue;$('source').append(node('p','TEXT '+key.toUpperCase()));const text=sources[key];const escaped=term.split(' ').map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('\\s+');const m=new RegExp('\\b'+escaped+'\\b','i').exec(text);if(!m){$('source').append(node('p','No exact surface-form match. Normalization may have changed the token.'));continue;}const start=Math.max(0,m.index-120),end=Math.min(text.length,m.index+m[0].length+170),q=node('blockquote','');q.append(document.createTextNode((start?'…':'')+text.slice(start,m.index)),node('mark',m[0]),document.createTextNode(text.slice(m.index+m[0].length,end)+(end<text.length?'…':'')));$('source').append(q);}}
$('export').onclick=()=>{if(!result)return;const rows=[['text','term','count','per_10000_retained_words']];for(const k of ['a','b'])if(result[k])for(const t of result[k].terms)rows.push([k.toUpperCase(),t.term,t.count,t.rate.toFixed(4)]);const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='text-mining-keywords.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
})();
